package com.auditlog.service.entity;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="audit_event") public class AuditEvent{
 @Id private UUID id;@Column(nullable=false,unique=true) private long sequenceNumber;@Column(nullable=false) private String eventType;@Column(nullable=false) private String actorId;@Column(nullable=false) private String resourceType;@Column(nullable=false) private String resourceId;@Column(nullable=false,columnDefinition="jsonb") private String payload;@Column(nullable=false) private Instant eventTimestamp;@Column(nullable=false,length=64) private String previousHash;@Column(nullable=false,length=64) private String currentHash;@Column(nullable=false) private Instant createdAt;@Column(nullable=false) private boolean archived;private UUID archiveBatchId;
 protected AuditEvent(){} public AuditEvent(UUID id,long seq,String type,String actor,String rt,String rid,String payload,Instant ts,String prev,String cur){this.id=id;sequenceNumber=seq;eventType=type;actorId=actor;resourceType=rt;resourceId=rid;this.payload=payload;eventTimestamp=ts;previousHash=prev;currentHash=cur;createdAt=Instant.now();}
 public UUID getId(){return id;} public long getSequenceNumber(){return sequenceNumber;} public String getEventType(){return eventType;} public String getActorId(){return actorId;} public String getResourceType(){return resourceType;} public String getResourceId(){return resourceId;} public String getPayload(){return payload;} public Instant getEventTimestamp(){return eventTimestamp;} public String getPreviousHash(){return previousHash;} public String getCurrentHash(){return currentHash;} public Instant getCreatedAt(){return createdAt;} public boolean isArchived(){return archived;} public UUID getArchiveBatchId(){return archiveBatchId;} public void archive(UUID batch){archived=true;archiveBatchId=batch;}
}
